<template>
  <section id="shipping-addresses" class="address-management" aria-labelledby="addresses-title" :aria-busy="loading || saving">
    <header class="section-heading"><div><h2 id="addresses-title">{{ formOpen ? (editingId?'Chỉnh sửa địa chỉ':'Thêm địa chỉ nhận hàng') : 'Địa chỉ nhận hàng' }}</h2><p class="muted">{{ formOpen?'Các trường có dấu * là bắt buộc.':'Quản lý người nhận và nơi giao hàng của bạn.' }}</p></div><button v-if="!formOpen" ref="addButton" class="button button-primary" :disabled="saving || loading || refreshRequired" @click="edit()">Thêm địa chỉ</button></header>
    <p v-if="loading" role="status">Đang tải địa chỉ…</p>
    <div v-if="error" ref="errorSummary" tabindex="-1" role="alert" class="marketplace-error"><p>{{ error }}</p><ul v-if="Object.keys(fieldErrors).length"><li v-for="(message,key) in fieldErrors" :key="key"><a :href="'#address-'+key" @click.prevent="focusField(key)">{{ message }}</a></li></ul><button v-if="!formOpen" class="button button-outline" :disabled="saving || loading" @click="load">Tải lại địa chỉ</button></div>
    <p v-if="notice" role="status" class="marketplace-success">{{ notice }}</p>
    <form v-if="formOpen" class="address-form" novalidate @submit.prevent="save">
      <fieldset v-for="group in groups" :key="group.title" :disabled="saving"><legend>{{ group.title }}</legend><p v-if="group.help" class="muted">{{ group.help }}</p><div class="address-fields"><div v-for="field in group.fields" :key="field.key" :class="{'address-field-wide':field.key==='addressDetail'}"><label :for="'address-'+field.key">{{ field.label }}{{ field.required?' *':'' }}</label><input :id="'address-'+field.key" v-model="form[field.key]" :type="field.key==='phone'?'tel':'text'" :maxlength="field.max" :autocomplete="field.autocomplete || 'off'" :required="field.required" :aria-invalid="!!fieldErrors[field.key]" :aria-describedby="fieldErrors[field.key]?'address-error-'+field.key:undefined"/><p v-if="fieldErrors[field.key]" :id="'address-error-'+field.key" class="marketplace-error">{{ fieldErrors[field.key] }}</p></div></div></fieldset>
      <fieldset :disabled="saving"><legend>Tùy chọn</legend><label for="address-label">Tên địa chỉ (tùy chọn)</label><input id="address-label" v-model="form.label" maxlength="80" placeholder="Ví dụ: Nhà riêng, văn phòng" :aria-invalid="!!fieldErrors.label" :aria-describedby="fieldErrors.label?'address-error-label':undefined"/><p v-if="fieldErrors.label" id="address-error-label" class="marketplace-error">{{ fieldErrors.label }}</p><label class="checkbox-label"><input v-model="form.isDefault" type="checkbox"/>Đặt làm địa chỉ mặc định</label></fieldset>
      <div class="button-row"><button class="button button-primary" :disabled="saving" type="submit">{{ saving?'Đang lưu…':'Lưu địa chỉ' }}</button><button class="button button-outline" :disabled="saving" type="button" @click="closeForm">Hủy</button></div>
    </form>
    <template v-else><p v-if="!loading && !error && !addresses.length" class="address-empty">Bạn chưa có địa chỉ nhận hàng. Thêm địa chỉ đầu tiên để dùng làm mặc định.</p>
      <ul v-if="!refreshRequired" class="address-list"><li v-for="address in addresses" :key="address.id" class="address-row"><div class="address-content"><h3>{{ address.recipientName }}<span v-if="address.isDefault" class="status-badge">Mặc định</span></h3><p class="marketplace-address-phone">{{ address.phone }}<span v-if="address.label"> · {{ address.label }}</span></p><p>{{ [address.addressDetail,address.wardName,address.districtName,address.provinceName].filter(Boolean).join(', ') }}</p></div><div class="address-actions"><button class="button button-outline" :disabled="saving" :aria-label="'Sửa địa chỉ '+address.recipientName" @click="edit(address)">Chỉnh sửa</button><button v-if="!address.isDefault" class="marketplace-text-button" :disabled="saving" @click="makeDefault(address)">Đặt mặc định</button><button class="marketplace-text-button marketplace-danger" :disabled="saving" :aria-label="'Xóa địa chỉ '+address.recipientName" @click="confirmDelete(address)">Xóa</button></div><div v-if="deleteId===address.id" class="address-confirm" role="group" aria-label="Xác nhận xóa địa chỉ"><p>Xóa địa chỉ của {{ address.recipientName }} tại {{ address.addressDetail }}?</p><button class="button marketplace-danger" :disabled="saving" @click="remove(address)">Xác nhận xóa</button><button class="button button-outline" :disabled="saving" @click="cancelDelete(address)">Giữ địa chỉ</button></div></li></ul>
    </template>
  </section>
</template>
<script setup>
import {ref,computed,onMounted,onBeforeUnmount,nextTick} from 'vue';
import {onBeforeRouteLeave,onBeforeRouteUpdate} from 'vue-router';
import {marketplaceRequest as request} from '../../services/marketplace.js';
import {useAuth} from '../../composables/useAuth.js';
const {user}=useAuth();
const addresses=ref([]),loading=ref(true),saving=ref(false),error=ref(''),fieldErrors=ref({}),notice=ref(''),refreshRequired=ref(false);
const formOpen=ref(false),editingId=ref(null),deleteId=ref(null),form=ref({}),original=ref(''),errorSummary=ref(null),addButton=ref(null);
const groups=[{title:'Thông tin người nhận',fields:[{key:'recipientName',label:'Họ tên người nhận',required:true,max:150,autocomplete:'shipping name'},{key:'phone',label:'Số điện thoại',required:true,max:30,autocomplete:'shipping tel'}]},{title:'Địa chỉ giao hàng',help:'Nhập tên tỉnh/thành phố và phường/xã hiện tại. Quận/huyện không bắt buộc.',fields:[{key:'provinceName',label:'Tỉnh / Thành phố',required:true,max:150,autocomplete:'shipping address-level1'},{key:'wardName',label:'Phường / Xã',required:true,max:150,autocomplete:'shipping address-level2'},{key:'districtName',label:'Quận / Huyện (nếu cần)',max:150},{key:'addressDetail',label:'Số nhà, tên đường và địa chỉ chi tiết',required:true,max:500,autocomplete:'shipping street-address'}]}];
const fields=groups.flatMap(g=>g.fields),dirty=computed(()=>formOpen.value&&JSON.stringify(form.value)!==original.value);
function canLeave(){if(!user.value)return true;if(saving.value)return false;return !dirty.value || window.confirm('Bạn có thay đổi chưa lưu. Rời khỏi biểu mẫu và bỏ các thay đổi?');}
onBeforeRouteLeave(canLeave);onBeforeRouteUpdate((to,from)=>to.query.section===from.query.section || canLeave());
function unload(e){if(dirty.value||saving.value){e.preventDefault();e.returnValue='';}}
onMounted(()=>{load();window.addEventListener('beforeunload',unload);});onBeforeUnmount(()=>window.removeEventListener('beforeunload',unload));
async function focusField(key){document.getElementById('address-'+key)?.focus();}
async function showError(e){error.value=e.message||'Không thể kết nối máy chủ. Vui lòng thử lại.';fieldErrors.value=e.fields||{};await nextTick();errorSummary.value?.focus();}
async function load(){if(loading.value&&!refreshRequired.value&&addresses.value.length)return;loading.value=true;error.value='';try{addresses.value=await request('/account/addresses');refreshRequired.value=false;}catch(e){await showError(e);}finally{loading.value=false;}}
async function edit(address){if(saving.value||refreshRequired.value)return;editingId.value=address?.id||null;form.value=Object.fromEntries([...fields,{key:'label'}].map(f=>[f.key,address?.[f.key]||'']));form.value.isDefault=address?.isDefault||false;original.value=JSON.stringify(form.value);formOpen.value=true;deleteId.value=null;error.value='';fieldErrors.value={};notice.value='';await nextTick();focusField('recipientName');}
async function closeForm(){if(!canLeave())return;formOpen.value=false;error.value='';fieldErrors.value={};await nextTick();addButton.value?.focus();}
async function mutate(operation,message){if(saving.value)return;saving.value=true;error.value='';fieldErrors.value={};notice.value='';let committed=false;
  try{await operation();committed=true;formOpen.value=false;deleteId.value=null;original.value='';notice.value=message;refreshRequired.value=true;
    try{addresses.value=await request('/account/addresses');refreshRequired.value=false;}catch{await showError({message:'Thay đổi đã được lưu. Chưa tải được danh sách mới; hãy tải lại địa chỉ trước khi thao tác tiếp.'});}
  }catch(e){await showError(e);}finally{saving.value=false;await nextTick();if(committed&&!error.value)addButton.value?.focus();}}
async function save(){if(saving.value)return;const errors={};for(const field of fields)if(field.required&&!String(form.value[field.key]||'').trim())errors[field.key]='Vui lòng nhập '+field.label.toLowerCase()+'.';if(form.value.phone&&!/^(0|\+84)[0-9\s.-]{8,14}$/.test(form.value.phone.trim()))errors.phone='Nhập số điện thoại Việt Nam hợp lệ.';if(Object.keys(errors).length){await showError({message:'Kiểm tra các trường được đánh dấu bên dưới.',fields:errors});return;}return mutate(()=>request('/account/addresses'+(editingId.value?'/'+editingId.value:''),editingId.value?'PUT':'POST',{...form.value}),'Đã lưu địa chỉ.');}
function makeDefault(address){return mutate(()=>request('/account/addresses/'+address.id+'/default','PATCH'),'Đã đổi địa chỉ mặc định.');}
function remove(address){return mutate(()=>request('/account/addresses/'+address.id,'DELETE'),'Đã xóa địa chỉ.');}
async function confirmDelete(address){deleteId.value=address.id;await nextTick();document.querySelector('.address-confirm button')?.focus();}
async function cancelDelete(address){deleteId.value=null;await nextTick();document.querySelector('[aria-label="Xóa địa chỉ '+address.recipientName+'"]')?.focus();}
</script>
